export type SessionText = keyof typeof sessionStrings
export const sessionText = (language: Language, label: SessionText): string => sessionStrings[label][languageColumn[language]]

export function translateSessionMessage(language: Language, message: string): string {
  return Object.hasOwn(sessionStrings, message) ? sessionText(language, message as SessionText) : message
}

